{
  "sceneId": "s-001",
  "claims": [
    {
      "entity": "loc-harben-foyer",
      "attribute": "police_presence",
      "value": "Inspector Lane and one constable; foyer cordoned with tape",
      "quote": "Inspector Lane stood in the small foyer with her collar up, a constable behind her, the hall already marked off with a strip of tape that had more dignity than utility."
    },
    {
      "entity": "char-inspector-margot-lane",
      "attribute": "instruction_to_ellis_arrival",
      "value": "Don't touch anything until forensics are here, Ellis",
      "quote": "“Don’t touch anything until forensics are here, Ellis,” she said when she saw me."
    },
    {
      "entity": "char-anna-rowe",
      "attribute": "found_body",
      "value": "Anna Rowe found Lucius Harben at his desk and summoned the police",
      "quote": "Anna Rowe met me at the study door. She had been the one to find him."
    },
    {
      "entity": "loc-harben-study",
      "attribute": "door_state",
      "value": "study door shut and locked from inside with brass key in lock",
      "quote": "The study door was shut. A heavy brass key sat in its lock, the metal dulled by years of handling and scored along one edge."
    },
    {
      "entity": "obj-brass-key",
      "attribute": "location",
      "value": "in the study door lock on the study side",
      "quote": "A heavy brass key sat in its lock, the metal dulled by years of handling and scored along one edge."
    },
    {
      "entity": "loc-harben-study",
      "attribute": "smell",
      "value": "oil, paper, and faint tang of metal",
      "quote": "The room beyond smelled of oil and paper and a faint, sharp tang of metal."
    },
    {
      "entity": "obj-longcase-clock",
      "attribute": "position",
      "value": "against the far wall of the study",
      "quote": "The longcase clock took up the far wall, an upright thing of walnut and gilt that pulled the light toward it."
    },
    {
      "entity": "obj-longcase-clock",
      "attribute": "hands_state",
      "value": "stopped at 11:17",
      "quote": "Its hands were frozen at eleven seventeen; the pendulum hung motionless, a dark tongue."
    },
    {
      "entity": "obj-longcase-clock",
      "attribute": "access_panel_state",
      "value": "rear access panel ajar with latch crooked",
      "quote": "the access panel at the rear of the case was a hair ajar, a sliver of inner brass visible where the latch sat crooked."
    },
    {
      "entity": "obj-ivory-revolver",
      "attribute": "display_status",
      "value": "missing from display; empty mount labelled 'IVORY REVOLVER'",
      "quote": "One mount was empty. A little brass label under the gap read IVORY REVOLVER in neat type; the mounting beneath it showed the ghost of a shape, the crushed velvet where the grip had rested."
    },
    {
      "entity": "char-lucius-harben",
      "attribute": "position_at_discovery",
      "value": "seated at his desk with shoulders folded forward, fingers curled over a torn scrap",
      "quote": "Lucius Harben sat at his desk with his shoulders folded forward as if in sleep. The back of his head caught the light; his fingers curled over a torn scrap."
    },
    {
      "entity": "obj-torn-note",
      "attribute": "visible_fragment_text",
      "value": "do not wind",
      "quote": "In his palm was a torn note, no larger than my thumb. The fragment I could see read, simply, do not wind."
    },
    {
      "entity": "loc-harben-study",
      "attribute": "desk_marking_near_body",
      "value": "neat, round mark on the blotter beside his hand consistent with a single shot",
      "quote": "A neat, round mark on the wood, the kind a single shot makes, stained the blotter beside his hand."
    },
    {
      "entity": "obj-black-thread",
      "attribute": "location_found",
      "value": "tangled at base of longcase clock",
      "quote": "At the base of the clock, tangled in the carved scrollwork, a black thread hung, waxed and stiff."
    },
    {
      "entity": "loc-harben-study",
      "attribute": "windows_state",
      "value": "latched with unbroken glass",
      "quote": "The windows were latched and the glass unbroken."
    }
  ],
  "presentEntities": [
    "char-ellis-fletcher",
    "char-inspector-margot-lane",
    "char-anna-rowe",
    "char-lucius-harben",
    "loc-harben-study",
    "loc-harben-foyer",
    "obj-longcase-clock",
    "obj-ivory-revolver",
    "obj-brass-key",
    "obj-torn-note",
    "obj-black-thread"
  ],
  "promises": [
    {
      "id": "promise-investigate-ivory",
      "promise": "Explain how the ivory revolver came to be absent from the display and whether its absence relates to Lucius Harben's death",
      "quote": "One mount was empty. A little brass label under the gap read IVORY REVOLVER in neat type; the mounting beneath it showed the ghost of a shape, the crushed velvet where the grip had rested.",
      "dueByScene": "s-010"
    },
    {
      "id": "promise-note-origin",
      "promise": "Determine the provenance and meaning of the torn note fragment 'do not wind' and whether it was written by Lucius or placed there",
      "quote": "In his palm was a torn note, no larger than my thumb. The fragment I could see read, simply, do not wind.",
      "dueByScene": "s-005"
    }
  ],
  "paysOff": []
}

{
  "sceneId": "s-002",
  "claims": [
    {
      "entity": "obj-longcase-clock",
      "attribute": "access_panel_state",
      "quote": "The rear access panel was a hair ajar and the latch sat crooked where it should have been flush.",
      "value": "rear access panel ajar with latch crooked"
    },
    {
      "entity": "obj-longcase-clock",
      "attribute": "hands_state",
      "quote": "Its hands were frozen at eleven seventeen; the pendulum hung motionless.",
      "value": "stopped at 11:17"
    },
    {
      "entity": "obj-longcase-clock",
      "attribute": "weights_position",
      "quote": "At the base, tucked behind the inner brass and snagged on a small screw, a length of black thread hung, waxed and stiff.",
      "value": "weights position not described in this scene"
    },
    {
      "entity": "obj-black-thread",
      "attribute": "location_found",
      "quote": "At the base, tucked behind the inner brass and snagged on a small screw, a length of black thread hung, waxed and stiff.",
      "value": "caught on inner bracket at clock base, threading up behind the movement; dust line present above thread and cleaner below"
    },
    {
      "entity": "obj-envelope",
      "attribute": "typed_threat_text",
      "quote": "When I tilted it the typed line showed through the thin paper, blunt and plain: “DO NOT SELL THE IVORY REVOLVER. THIS IS YOUR LAST WARNING.”",
      "value": "DO NOT SELL THE IVORY REVOLVER. THIS IS YOUR LAST WARNING."
    },
    {
      "entity": "obj-envelope",
      "attribute": "flap_crease",
      "quote": "On Lucius Harben’s desk a sealed envelope sat with a shallow diagonal crease across the flap.",
      "value": "shallow diagonal crease across flap, as if pressed by a thumb"
    },
    {
      "entity": "obj-ivory-revolver",
      "attribute": "display_status",
      "quote": "Opposite the clock the weapons case kept its quiet. One mount was empty; the brass plaque beneath read IVORY REVOLVER. The velvet where a grip had lain was pressed down, an absence that made the rest of the row look oddly whole by comparison.",
      "value": "missing from display; mount shows crushed velvet where grip had lain"
    },
    {
      "entity": "char-anna-rowe",
      "attribute": "last_seen_lucius_time",
      "quote": "She told me she had seen Mr. Harben at breakfast, just after eight.",
      "value": "last seen Lucius at ~08:05-08:15"
    },
    {
      "entity": "char-anna-rowe",
      "attribute": "observed_household_movements",
      "quote": "She said Mrs. Harben had left for town a little after nine, and that Mr. Reed had called by later and left before eleven.",
      "value": "Iris left for town ~09:05; Thomas present earlier, left before 11:00; Thomas observed in workshop"
    },
    {
      "entity": "char-iris-harben",
      "attribute": "alibi",
      "quote": "She gave a neat account — she’d been in town that morning to discuss payments connected with the collection —",
      "value": "in town that morning discussing payments for collection; departed ~09:05 (per Anna)"
    },
    {
      "entity": "char-iris-harben",
      "attribute": "behavioural_tell",
      "quote": "she smoothed the edge of her hand against her wedding band.",
      "value": "absentive smoothing of wedding band while speaking (nervous gesture beneath composed exterior)"
    },
    {
      "entity": "char-thomas-reed",
      "attribute": "alibi",
      "quote": "He said he’d been in the workshop across the square until just before eleven and that a neighbour could confirm it.",
      "value": "at workshop until just before 11:00; neighbour witness claimed"
    },
    {
      "entity": "char-thomas-reed",
      "attribute": "behavioural_tell",
      "quote": "he kept rubbing the pad of his thumb and forefinger together in that restless way of men who handle small gears.",
      "value": "rubs thumb and forefinger pad when anxious or trying to steady himself"
    },
    {
      "entity": "char-inspector-margot-lane",
      "attribute": "instruction_to_ellis_arrival",
      "quote": "She closed the door behind her and said, in the very words she’d used when I first arrived, “Don’t touch anything until forensics are here, Ellis.”",
      "value": "Don't touch anything until forensics are here, Ellis"
    }
  ],
  "presentEntities": [
    "char-ellis-fletcher",
    "char-iris-harben",
    "char-thomas-reed",
    "char-inspector-margot-lane",
    "char-anna-rowe",
    "loc-harben-study",
    "loc-harben-foyer",
    "obj-longcase-clock",
    "obj-ivory-revolver",
    "obj-black-thread",
    "obj-envelope"
  ],
  "promises": [],
  "paysOff": []
}

